local ECSComponent = import("Frame.ECS.ECSComponent")
local checkInt = checkInt

---@class CardSkinComponent
local CardSkinComponent = Class("CardSkinComponent", ECSComponent)


function CardSkinComponent:__init()
    self.name = "CardSkinComponent"

    ---@type table<integer, integer> @ 玩家所拥有的所有皮肤记录（key：皮肤id，value：皮肤id）
    self._cardSkins = nil

    ---@type table<integer, integer> @ 卡牌等级map（key：皮肤id，value：皮肤等级）
    self._skinId2Level = nil

    ---@type table<integer, integer[]> @ 卡牌拥有的皮肤设定列表（key：卡牌id，value：皮肤id列表）
    self._skinListMap = {}

    ---@type table<integer, boolean> @ 卡牌拥有的皮肤对应的new状态（key：卡牌id，value：new状态）
    self._skinId2New   = {}
end


function CardSkinComponent:__delete()
    self.name          = nil
    self._cardSkins    = nil
    self._skinId2Level = nil
    self._skinListMap  = nil
    
end


function CardSkinComponent:Initial(jsonData, skinLevelUpTimes)
    self._cardSkins    = {}
    self._skinId2Level = {}
    self._skinLevelUpTimes = skinLevelUpTimes

    for i, v in ipairs(checkTable(jsonData)) do
        self:AddCardSkin(v.skinId, true)
        self:SetSkinLevelById(v.skinId, v.level)
    end

    self:InitCardSkinIdList()
end


---当前玩家所拥有的所有皮肤
---@return table<integer, integer>
function CardSkinComponent:GetAllCardSkinTable()
    return self._cardSkins
end


--- 根据 卡屁皮肤id 获取皮肤等级
---@param skinId integer
---@return integer
function CardSkinComponent:GetSkinLevelById(skinId, skinMaxLevel)
    if skinMaxLevel == nil then
        ---@type CardSkinVo
        local vo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
        if vo then
            skinMaxLevel = vo.skinMaxLevel
        else
            skinMaxLevel = 0
        end
    end
    --- 皮肤养成最大等级 0：不可养成 >0 最大养成等级
    local lv = checkInt(self._skinId2Level[checkInt(skinId)])
    return lv == 0 and (skinMaxLevel == 0 and 0 or 1) or lv
end


--- 设置 指定皮肤id 的等级
---@param skinId integer
---@param level integer
function CardSkinComponent:SetSkinLevelById(skinId, level)
    local cardSkin = checkInt(skinId)
    if cardSkin <= 0 then
        return
    end
    self._skinId2Level[cardSkin] = checkInt(level)

    -- 卡牌收集 增加已收集 皮肤升级次数
    if self:GetSkinLevelById(skinId) > 0 then
        local entity = GameUtils.GetEntity()
        if entity:IsCompExistsByName(ECSComponentType.Constants.IllustratedHandbookComponent) then
            ---@type IllustratedHandbookComponent
            local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
            illustratedHandbookComp:CheckAdditionStorage(Constants.CardCollectionType.SKIN_LV, nil, skinId)
            illustratedHandbookComp:CheckAdditionSkinLevelRedPoint()
        end
    end
end


--- 是否 已有皮肤
---@param skinId integer @ 卡牌皮肤id
---@return boolean
function CardSkinComponent:IsHasSkin(skinId)
    return checkInt(self._cardSkins[checkInt(skinId)]) > 0
end


--- 新增卡牌皮肤
---@param skinId integer @ 卡牌皮肤id
function CardSkinComponent:AddCardSkin(skinId, isInitiated)
    local cardSkin = checkInt(skinId)
    if cardSkin <= 0 then
        return
    end

    -- 如果是新增
    if not self:IsHasSkin(cardSkin) then
        ---@type CardSkinVo
        local vo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardSkin)
        if vo then
            if vo.skinMaxLevel > 0 then
                ---@type CardSkinComponent
                local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
                cardSkinComponent:SetSkinLevelById(cardSkin, 1)
            end

            if not isInitiated and vo.tag > 2 then
                ---【角色卡牌皮肤表】tag=1和2的，不显示小红点，tag=其他值时，显示小红点
                self:SetIsNewBySkinId(cardSkin, true)
            end
            
        end
        
    end
    self._cardSkins[cardSkin] = cardSkin

    -- 图鉴增加已收集 皮肤
    local entity = GameUtils.GetEntity()
    if entity:IsCompExistsByName(ECSComponentType.Constants.IllustratedHandbookComponent) then
        ---@type IllustratedHandbookComponent
        local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
        illustratedHandbookComp:CheckHandbookStorage(Constants.HandbookCollectionType.SKIN, cardSkin)
        illustratedHandbookComp:CheckHandbookSkinRedPoint()
    end

end

---GetIsNewBySkinId
---通关皮肤id获取是否是new
function CardSkinComponent:GetIsNewBySkinId(skinId)
    return self._skinId2New[checkNumber(skinId)] == true
end
---SetIsNewBySkinId
---设置皮肤new状态
function CardSkinComponent:SetIsNewBySkinId(skinId, isNew)
    self._skinId2New[checkNumber(skinId)] = isNew
end
function CardSkinComponent:GetSkinId2New()
    return self._skinId2New
end


--- 记录卡牌皮肤id定义
function CardSkinComponent:InitCardSkinIdList()
    local cardSkinListMap = {}
    for voIndex, skinVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting113, 'CardSkinVo')) do
        local cardId = checkInt(skinVo.roleId)
        local skinId = checkInt(skinVo.skinId)
        if skinVo.isHandbook then
            if not cardSkinListMap[cardId] then
                cardSkinListMap[cardId] = {}
            end
            table.insert(cardSkinListMap[cardId], skinId)
        end
    end
    self._skinListMap = cardSkinListMap
end

---@param cardId number
---@param isOwnMaxLv? boolean
---@return table?
function CardSkinComponent:GetSkinId2LvByCardId(cardId, isOwnMaxLv)
    local cardSkinIds = CardConfMgr:GetInstance():GetCardSkinsByCardId(cardId)
    if cardSkinIds == nil then return end

    local skinId2Lv
    for index, cardSkinId in ipairs(cardSkinIds) do
        local cardSkinId_ = checkNumber(cardSkinId)
        if self:IsHasSkin(cardSkinId_) then
            skinId2Lv = skinId2Lv or {}
            skinId2Lv[cardSkinId_] = self:GetSkinLevelById(cardSkinId_) or 1
        end

    end
    
    return skinId2Lv
end


--- 根据制定 卡牌id，获取全部的皮肤id
---@param cardId integer
---@return integer[]
function CardSkinComponent:GetCardSkinIdList(cardId)
    return checkTable(self._skinListMap[checkInt(cardId)])
end

function CardSkinComponent:AddSkinLevelUpTimes(times)
    self._skinLevelUpTimes = self._skinLevelUpTimes + times
end

function CardSkinComponent:GetSkinLevelUpTimes()
    return self._skinLevelUpTimes
end


return CardSkinComponent